@custom-variant dark (&:where(.dark, .dark *));

:root {
  --riff-black: #0B0B0B;
  --riff-ink: #141414;
  --riff-paper: #F4F0E8;
  --riff-crimson: #C92533;
  --riff-deep-red: #741B24;
  --riff-grey: #AAA8A6;
  --riff-dim: #777575;
  --riff-rule: rgba(244, 240, 232, 0.22);
}

@layer base {
  html {
    background-color: var(--riff-black);
    color: var(--riff-paper);
    font-family: var(--font-plus-jakarta), "Plus Jakarta Sans", -apple-system, BlinkMacSystemFont, sans-serif;
    scroll-behavior: smooth;
  }

  body {
    background-color: var(--riff-black);
    color: var(--riff-paper);
    overflow-x: hidden;
  }

  /* High-visibility accessible focus rings on dark print canvas */
  *:focus-visible {
    outline: 2px solid var(--riff-crimson);
    outline-offset: 3px;
  }
}

.font-editorial {
  font-family: var(--font-bodoni-moda), "Bodoni Moda", Georgia, serif;
}

.font-condensed {
  font-family: var(--font-barlow-condensed), "Barlow Condensed", Impact, sans-serif;
}

.font-sans-ui {
  font-family: var(--font-plus-jakarta), "Plus Jakarta Sans", -apple-system, BlinkMacSystemFont, sans-serif;
}

.font-mono-code {
  font-family: var(--font-jetbrains-mono), "JetBrains Mono", monospace;
}

/* Analog photographic grain overlay */
.riff-grain-overlay {
  background-image: url("/assets/noise-tile.png");
  background-repeat: repeat;
  background-size: 160px 160px;
  opacity: 0.24;
  pointer-events: none;
}

/* Concentrated halftone dot patches matching reference corners and collage backings */
.halftone-patch {
  background-image: radial-gradient(rgba(244, 240, 232, 0.16) 1.25px, transparent 1.35px);
  background-size: 7px 7px;
}

.halftone-patch-crimson {
  background-image: radial-gradient(rgba(201, 37, 51, 0.28) 1.5px, transparent 1.6px);
  background-size: 8px 8px;
}

.halftone-patch-fine {
  background-image: radial-gradient(rgba(244, 240, 232, 0.11) 1px, transparent 1.1px);
  background-size: 5px 5px;
}

/* Torn zine edge clip paths */
.torn-paper-top {
  clip-path: polygon(
    0% 6%, 4% 2%, 9% 7%, 15% 1%, 22% 5%, 28% 0%, 35% 6%, 42% 2%,
    49% 7%, 56% 1%, 63% 5%, 71% 0%, 78% 6%, 85% 2%, 92% 7%, 97% 1%,
    100% 5%, 100% 100%, 0% 100%
  );
}

.torn-paper-strip {
  clip-path: polygon(
    0% 4%, 5% 0%, 12% 5%, 19% 1%, 27% 4%, 36% 0%, 44% 5%, 53% 1%,
    61% 4%, 70% 0%, 79% 5%, 88% 1%, 95% 4%, 100% 1%,
    99% 96%, 93% 100%, 85% 95%, 76% 99%, 67% 95%, 58% 100%,
    49% 95%, 40% 99%, 31% 95%, 22% 100%, 14% 96%, 6% 99%, 0% 95%
  );
}

/* Perforated concert ticket edge */
.ticket-perforated {
  clip-path: polygon(
    0% 6%, 3% 0%, 97% 0%, 100% 6%,
    100% 22%, 97% 26%, 100% 30%,
    100% 48%, 97% 52%, 100% 56%,
    100% 74%, 97% 78%, 100% 82%,
    100% 94%, 97% 100%, 3% 100%, 0% 94%,
    0% 82%, 3% 78%, 0% 74%,
    0% 56%, 3% 52%, 0% 48%,
    0% 30%, 3% 26%, 0% 22%
  );
}

/* Screen-print misregistration button hover */
.btn-screenprint {
  position: relative;
  transition: transform 160ms cubic-bezier(0.16, 1, 0.3, 1), box-shadow 160ms cubic-bezier(0.16, 1, 0.3, 1);
}

.btn-screenprint:hover {
  transform: translate(-2px, -2px);
  box-shadow: 4px 4px 0px rgba(244, 240, 232, 0.28);
}

.btn-screenprint:active {
  transform: translate(0px, 0px);
  box-shadow: 1px 1px 0px rgba(244, 240, 232, 0.2);
}

/* Slow ambient vinyl rotation */
@keyframes riff-spin-slow {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

.animate-vinyl-slow {
  animation: riff-spin-slow 24s linear infinite;
}

.animate-vinyl-fast {
  animation: riff-spin-slow 3.2s linear infinite;
}

/* On-load paper-slit shutter reveal */
@keyframes paper-slit-reveal {
  0% {
    clip-path: inset(0 100% 0 0);
    transform: translateY(8px);
    opacity: 0.2;
  }
  100% {
    clip-path: inset(0 0% 0 0);
    transform: translateY(0);
    opacity: 1;
  }
}

.reveal-paper-slit-1 {
  animation: paper-slit-reveal 550ms cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

.reveal-paper-slit-2 {
  animation: paper-slit-reveal 700ms cubic-bezier(0.16, 1, 0.3, 1) 90ms both;
}

.reveal-paper-slit-3 {
  animation: paper-slit-reveal 820ms cubic-bezier(0.16, 1, 0.3, 1) 180ms both;
}

/* Section 01-04 Art-Directed Motion Choreography */
@keyframes riff-sleeve-wipe {
  0% {
    clip-path: inset(0 100% 0 0);
    transform: translateX(12px) scale(0.985);
    opacity: 0.35;
  }
  100% {
    clip-path: inset(0 0% 0 0);
    transform: translateX(0) scale(1);
    opacity: 1;
  }
}

@keyframes riff-ring-expand {
  0% {
    clip-path: circle(14% at 68% 30%);
    transform: scale(0.98);
    opacity: 0.4;
  }
  100% {
    clip-path: circle(140% at 68% 30%);
    transform: scale(1);
    opacity: 1;
  }
}

@keyframes riff-band-sweep {
  0% {
    clip-path: circle(18% at 50% 44%);
    opacity: 0.45;
  }
  100% {
    clip-path: circle(135% at 50% 44%);
    opacity: 1;
  }
}

@keyframes riff-ticket-whip {
  0% {
    clip-path: inset(0 0 0 100%);
    transform: translateX(-14px) rotate(-1.2deg);
    opacity: 0.3;
  }
  100% {
    clip-path: inset(0 0 0 0%);
    transform: translateX(0) rotate(0deg);
    opacity: 1;
  }
}

@keyframes riff-gatefold-unfold {
  0% {
    clip-path: inset(0 48% 0 0);
    transform: perspective(1100px) rotateY(-8deg) scale(0.98);
    opacity: 0.35;
  }
  100% {
    clip-path: inset(0 0% 0 0);
    transform: perspective(1100px) rotateY(0deg) scale(1);
    opacity: 1;
  }
}

.anim-sleeve-wipe {
  animation: riff-sleeve-wipe 460ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.anim-ring-expand {
  animation: riff-ring-expand 520ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.anim-band-sweep {
  animation: riff-band-sweep 440ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.anim-ticket-whip {
  animation: riff-ticket-whip 420ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.anim-gatefold-unfold {
  animation: riff-gatefold-unfold 480ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

/* Pause animations when user toggles motion off or prefers reduced motion */
.motion-paused .animate-vinyl-slow,
.motion-paused .animate-vinyl-fast,
.motion-paused .anim-sleeve-wipe,
.motion-paused .anim-ring-expand,
.motion-paused .anim-band-sweep,
.motion-paused .anim-ticket-whip,
.motion-paused .anim-gatefold-unfold {
  animation: none !important;
  clip-path: none !important;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  .animate-vinyl-slow,
  .animate-vinyl-fast,
  .reveal-paper-slit-1,
  .reveal-paper-slit-2,
  .reveal-paper-slit-3,
  .anim-sleeve-wipe,
  .anim-ring-expand,
  .anim-band-sweep,
  .anim-ticket-whip,
  .anim-gatefold-unfold {
    animation: none !important;
    clip-path: none !important;
    transform: none !important;
    opacity: 1 !important;
  }
}

